supabase/functions/submit-guest-order/in.beforeText:
import {
  MAX_TURNSTILE_TOKEN_LENGTH,
  extractTrustedClientIp,
  hmacSha256Hex,
  isUuid,
  normalizeJordanPhone,
  safeGatewayMessage,
  verifyTurnstileToken,
} from './security.ts';

declare const Deno: {
  env: {get(name: string): string | undefined};
  serve(handler: (request: Request) => Response | Promise<Response>): void;
};

interface GuestOrderGatewayBody {
  contractVersion?: unknown;
  idempotencyKey?: unknown;
  turnstileToken?: unknown;
  clientSessionId?: unknown;
  customer?: Record<string, unknown>;
  items?: unknown;
  promotionCode?: unknown;
  paymentMethod?: unknown;
  deliveryZone?: unknown;
  expectedQuote?: Record<string, unknown>;
}

const approvedOrigins = new Set([
  'https://alnawasreh.com',
  'https://nawasrah-store.pages.dev',
  'http://localhost:3002',
  'http://127.0.0.1:3002',
  'http://localhost:4174',
  'http://127.0.0.1:4174',
]);

const isApprovedOrigin = (origin: string | null) => {
  if (!origin) return false;
  if (approvedOrigins.has(origin)) return true;
  return /^https:\/\/[a-z0-9-]+\.nawasrah-store\.pages\.dev$/i.test(origin);
};

const corsHeaders = (origin: string | null): HeadersInit => ({
  'Access-Control-Allow-Origin': isApprovedOrigin(origin) ? origin! : 'null',
  'Access-Control-Allow-Headers': 'apikey, content-type, x-client-info',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
  'Content-Type': 'application/json; charset=utf-8',
  'Cache-Control': 'no-store',
  Vary: 'Origin',
});

const jsonResponse = (
  body: unknown,
  status: number,
  origin: string | null,
  extraHeaders: HeadersInit = {},
) => new Response(JSON.stringify(body), {
  status,
  headers: {...corsHeaders(origin), ...extraHeaders},
});

const text = (value: unknown, maxLength: number) =>
  typeof value === 'string' ? value.trim().slice(0, maxLength) : '';

const eventId = () => crypto.randomUUID();
const MAX_REQUEST_BODY_BYTES = 64 * 1024;
const MAX_GUEST_ORDER_LINE_ITEMS = 50;

async function readLimitedJsonBody(
  request: Request,
): Promise<{body?: GuestOrderGatewayBody; tooLarge?: boolean}> {
  const reader = request.body?.getReader();
  if (!reader) return {};

  const chunks: Uint8Array[] = [];
  let totalBytes = 0;
  while (true) {
    const {done, value} = await reader.read();
    if (done) break;
    totalBytes += value.byteLength;
    if (totalBytes > MAX_REQUEST_BODY_BYTES) {
      await reader.cancel();
      return {tooLarge: true};
    }
    chunks.push(value);
  }

  const bytes = new Uint8Array(totalBytes);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.byteLength;
  }

  try {
    return {body: JSON.parse(new TextDecoder().decode(bytes)) as GuestOrderGatewayBody};
  } catch {
    return {};
  }
}

function logSecurityEvent(
  event: string,
  requestId: string,
  details: Record<string, string | number | boolean> = {},
) {
  console.info(JSON.stringify({event, requestId, ...details}));
}

async function callRpc(
  supabaseUrl: string,
  serviceRoleKey: string,
  functionName: string,
  payload: Record<string, unknown>,
  fetchImpl: typeof fetch,
) {
  return fetchImpl(`${supabaseUrl}/rest/v1/rpc/${functionName}`, {
    method: 'POST',
    headers: {
      apikey: serviceRoleKey,
      Authorization: `Bearer ${serviceRoleKey}`,
      'Content-Type': 'application/json',
      Accept: 'application/json',
    },
    body: JSON.stringify(payload),
  });
}

interface GuestOrderHandlerDependencies {
  getEnv?: (name: string) => string | undefined;
  fetchImpl?: typeof fetch;
}

export async function handleGuestOrderRequest(
  request: Request,
  dependencies: GuestOrderHandlerDependencies = {},
): Promise<Response> {
  const getEnv = dependencies.getEnv ?? ((name: string) => Deno.env.get(name));
  const fetchImpl = dependencies.fetchImpl ?? fetch;
  const origin = request.headers.get('origin');
  const requestId = eventId();

  if (request.method === 'OPTIONS') {
    return new Response(null, {
      status: isApprovedOrigin(origin) ? 204 : 403,
      headers: corsHeaders(origin),
    });
  }
  if (request.method !== 'POST') {
    return jsonResponse({error: 'Method not allowed'}, 405, origin);
  }
  if (!isApprovedOrigin(origin)) {
    return jsonResponse({error: 'Origin is not allowed'}, 403, origin);
  }

  const contentLength = Number(request.headers.get('content-length') || '0');
  if (contentLength > MAX_REQUEST_BODY_BYTES) {
    return jsonResponse({error: 'راجع بيانات الطلب ثم حاول مرة أخرى.', code: 'invalid_request'}, 413, origin);
  }

  const supabaseUrl = getEnv('SUPABASE_URL')?.replace(/\/+$/, '');
  const serviceRoleKey = getEnv('SUPABASE_SERVICE_ROLE_KEY');
  const turnstileSecret = getEnv('TURNSTILE_SECRET_KEY');
  const hashSecret = getEnv('GUEST_ORDER_HASH_SECRET');
  const turnstileTestMode = getEnv('TURNSTILE_TEST_MODE') === 'true';
  const allowedHostnames = new Set<string>(
    (getEnv('TURNSTILE_ALLOWED_HOSTNAMES') || 'alnawasreh.com,nawasrah-store.pages.dev')
      .split(',')
      .map((hostname) => hostname.trim().toLowerCase())
      .filter(Boolean),
  );

  if (
    !supabaseUrl ||
    !serviceRoleKey ||
    !turnstileSecret ||
    !hashSecret ||
    hashSecret.length < 32
  ) {
    logSecurityEvent('gateway_configuration_error', requestId);
    return jsonResponse({
      error: 'تعذر إرسال الطلب مؤقتًا. حاول مرة أخرى.',
      code: 'gateway_unavailable',
    }, 503, origin);
  }

  const parsedRequest = await readLimitedJsonBody(request);
  if (parsedRequest.tooLarge) {
    return jsonResponse({error: 'راجع بيانات الطلب ثم حاول مرة أخرى.', code: 'invalid_request'}, 413, origin);
  }
  if (!parsedRequest.body) {
    return jsonResponse({error: 'راجع بيانات الطلب ثم حاول مرة أخرى.', code: 'invalid_request'}, 400, origin);
  }
  const body = parsedRequest.body;
  const contractVersion = text(body.contractVersion, 80);
  const isCustomerV2 = contractVersion === 'phase3-customer-reservation-v2';
  if (!isCustomerV2) {
    return jsonResponse({error: 'حدّث الصفحة وأعد المحاولة', code: 'unsupported_contract'}, 400, origin);
  }

  const idempotencyKey = text(body.idempotencyKey, 64);
  const clientSessionId = text(body.clientSessionId, 64);
  const turnstileToken = text(body.turnstileToken, MAX_TURNSTILE_TOKEN_LENGTH + 1);
  const customer = body.customer || {};
  const expectedQuote = body.expectedQuote || {};
  const items = Array.isArray(body.items) ? body.items : [];
  const phone = normalizeJordanPhone(customer.phone);
  const clientIp = extractTrustedClientIp(request.headers);

  if (!isUuid(idempotencyKey) || !isUuid(clientSessionId) || !phone || !clientIp) {
    return jsonResponse({error: 'راجع بيانات الطلب ثم حاول مرة أخرى.', code: 'invalid_request'}, 400, origin);
  }
  if (items.length > MAX_GUEST_ORDER_LINE_ITEMS) {
    return jsonResponse({
      error: `الحد الأقصى للطلب هو ${MAX_GUEST_ORDER_LINE_ITEMS} صنفًا. احذف صنفًا واحدًا على الأقل ثم حاول مرة أخرى.`,
      code: 'too_many_line_items',
    }, 400, origin);
  }
  if (!turnstileToken || turnstileToken.length > MAX_TURNSTILE_TOKEN_LENGTH) {
    logSecurityEvent('turnstile_missing', requestId);
    return jsonResponse({
      error: safeGatewayMessage(400, 'turnstile_required'),
      code: 'turnstile_required',
    }, 400, origin);
  }

  const turnstile = await verifyTurnstileToken({
    token: turnstileToken,
    remoteIp: clientIp,
    idempotencyKey,
    secret: turnstileSecret,
    allowedHostnames,
    testMode: turnstileTestMode,
    fetchImpl,
  });
  if (!turnstile.success) {
    logSecurityEvent('turnstile_failed', requestId, {
      duplicateOrExpired: turnstile['error-codes']?.includes('timeout-or-duplicate') === true,
    });
    return jsonResponse({
      error: safeGatewayMessage(400, 'turnstile_failed'),
      code: 'turnstile_failed',
    }, 400, origin);
  }

  const [ipHash, sessionHash, phoneHash] = await Promise.all([
    hmacSha256Hex(hashSecret, 'ip', clientIp),
    hmacSha256Hex(hashSecret, 'session', clientSessionId),
    hmacSha256Hex(hashSecret, 'phone', phone),
  ]);

  let authorizationResponse: Response;
  let authorization: {
    allowed?: boolean;
    reason?: string;
    retry_after_seconds?: number;
  };
  try {
    authorizationResponse = await callRpc(
      supabaseUrl,
      serviceRoleKey,
      'authorize_guest_order_gateway',
      {
        p_idempotency_key: idempotencyKey,
        p_ip_hash: ipHash,
        p_session_hash: sessionHash,
        p_phone_hash: phoneHash,
      },
      fetchImpl,
    );
    authorization = await authorizationResponse.json() as typeof authorization;
  } catch {
    logSecurityEvent('gateway_authorization_error', requestId);
    return jsonResponse({error: safeGatewayMessage(503, ''), code: 'gateway_unavailable'}, 503, origin);
  }

  if (!authorizationResponse.ok) {
    logSecurityEvent('gateway_authorization_error', requestId);
    return jsonResponse({error: safeGatewayMessage(503, ''), code: 'gateway_unavailable'}, 503, origin);
  }
  if (authorization.allowed !== true) {
    const retryAfter = Math.max(1, Number(authorization.retry_after_seconds) || 600);
    logSecurityEvent('rate_limit_rejected', requestId, {reason: authorization.reason || 'rate_limited'});
    return jsonResponse({
      error: safeGatewayMessage(429, 'rate_limited'),
      code: 'rate_limited',
      retryAfterSeconds: retryAfter,
    }, 429, origin, {'Retry-After': String(retryAfter)});
  }

  let orderResponse: Response;
  let orderResult: Record<string, unknown>;
  try {
    const rpcName = 'submit_guest_customer_order_v2';
    const rpcPayload = {
      p_idempotency_key: idempotencyKey,
      p_guest_phone_hash: phoneHash,
      p_guest_session_hash: sessionHash,
      p_customer_full_name: text(customer.fullName, 120),
      p_customer_phone: phone,
      p_governorate: text(customer.governorate, 80),
      p_city: text(customer.city, 80),
      p_area: text(customer.area, 120),
      p_street: text(customer.street, 300),
      p_building: text(customer.building, 120) || null,
      p_address_notes: text(customer.addressNotes, 500) || null,
      p_google_maps_url: text(customer.googleMapsUrl, 1000) || null,
      p_latitude: typeof customer.latitude === 'number' ? customer.latitude : null,
      p_longitude: typeof customer.longitude === 'number' ? customer.longitude : null,
      p_customer_notes: text(customer.customerNotes, 1000) || null,
      p_lines: items,
      p_promotion_code: text(body.promotionCode, 80) || null,
      p_payment_method: text(body.paymentMethod, 30),
      p_delivery_zone: text(body.deliveryZone, 30),
      p_expected_subtotal_in_minor_units:
        typeof expectedQuote.subtotalInMinorUnits === 'number'
          ? expectedQuote.subtotalInMinorUnits : null,
      p_expected_discount_in_minor_units:
        typeof expectedQuote.discountInMinorUnits === 'number'
          ? expectedQuote.discountInMinorUnits : null,
      p_expected_delivery_fee_in_minor_units:
        typeof expectedQuote.deliveryFeeInMinorUnits === 'number'
          ? expectedQuote.deliveryFeeInMinorUnits : null,
      p_expected_total_in_minor_units:
        typeof expectedQuote.totalInMinorUnits === 'number'
          ? expectedQuote.totalInMinorUnits : null,
    };
    orderResponse = await callRpc(
      supabaseUrl,
      serviceRoleKey,
      rpcName,
      rpcPayload,
      fetchImpl,
    );
    orderResult = await orderResponse.json() as Record<string, unknown>;
  } catch {
    logSecurityEvent('guest_order_gateway_error', requestId);
    try {
      await callRpc(supabaseUrl, serviceRoleKey, 'finalize_guest_order_gateway', {
        p_idempotency_key: idempotencyKey,
        p_outcome: 'gateway_error',
        p_order_id: null,
      }, fetchImpl);
    } catch {
      logSecurityEvent('gateway_finalize_error', requestId);
    }
    return jsonResponse({error: safeGatewayMessage(503, ''), code: 'gateway_unavailable'}, 503, origin);
  }

  const succeeded = orderResponse.ok && orderResult.success === true;
  const orderId = succeeded && isUuid(orderResult.order_id)
    ? orderResult.order_id
    : null;

  try {
    const finalizeResponse = await callRpc(supabaseUrl, serviceRoleKey, 'finalize_guest_order_gateway', {
      p_idempotency_key: idempotencyKey,
      p_outcome: succeeded ? 'succeeded' : 'order_rejected',
      p_order_id: orderId,
    }, fetchImpl);
    if (!finalizeResponse.ok) logSecurityEvent('gateway_finalize_error', requestId);
  } catch {
    logSecurityEvent('gateway_finalize_error', requestId);
  }

  if (!succeeded) {
    logSecurityEvent('guest_order_rejected', requestId);
    const message=typeof orderResult.message==='string'?orderResult.message:'';
    const parcelOnly=orderResult.code==='23514'&&message.startsWith('PARCEL209_UNIT_SALE_FORBIDDEN:');
    const changedFamily=orderResult.code==='40001'&&message.startsWith('PARCEL209_FAMILY_CHANGED_RETRY:');
    return jsonResponse({
      error: parcelOnly?'أحد الأصناف بيتباع بالطرد بس. احذف سطر المفرد واختر طرداً؛ لم تتغيّر السلة تلقائياً.'
        :changedFamily?'تغيّرت نكهات أحد الأصناف. حدّث السلة وراجعها قبل إرسال طلب جديد.'
        :'تعذر إكمال الطلب بهذه البيانات. راجع الكميات وحاول مرة أخرى.',
      code: parcelOnly?'parcel_only_sale_required':changedFamily?'product_methods_changed':'order_rejected',
    }, 400, origin);
  }

  logSecurityEvent('guest_order_accepted', requestId, {
    idempotentReplay: orderResult.idempotent_replay === true,
  });
  return jsonResponse(orderResult, 200, origin);
}

if (typeof Deno !== 'undefined') {
  Deno.serve((request) => handleGuestOrderRequest(request));
}

src/services/supabase/posV2.service.ts.beforeText:
import { isSupabaseConfigured, supabase } from '../../lib/supabase';
import type { PaymentMethod } from '../../types';
import {posV2ResultMatches,posV2RequestValid} from './posV2Validation';

export interface PosV2BaseUnitLine {
  commercial_line_kind: 'base_unit';
  product_id: string;
  base_quantity: number;
  price_authority?: 'server_catalog';
  line_discount_in_minor_units?: 0;
}

export interface PosV2LegacyParcelLine {
  commercial_line_kind: 'legacy_single_sku_parcel';
  product_id: string;
  parcel_quantity: number;
  units_per_parcel: number;
  price_authority?: 'server_catalog';
  line_discount_in_minor_units?: 0;
}

export interface PosV2ConfigurableParcelLine {
  commercial_line_kind: 'configurable_parcel';
  family_product_id: string;
  parcel_configuration_id: string;
  configuration_revision: number;
  price_authority?: 'server_catalog';
  line_discount_in_minor_units?: 0;
  parcel_instances: Array<{
    components: Array<{ product_id: string; base_quantity: number }>;
  }>;
}

export type PosV2Line =
  | PosV2BaseUnitLine
  | PosV2LegacyParcelLine
  | PosV2ConfigurableParcelLine;

export interface CreatePosSaleV2Input {
  warehouseId: string;
  branchId: string;
  customerId?: string;
  customerName?: string;
  paymentMethod: PaymentMethod;
  lines: PosV2Line[];
  discountInMinorUnits: number;
  amountReceivedInMinorUnits: number;
  idempotencyKey: string;
  initialPayment?: {amountInMinorUnits: number; method: 'cash' | 'cliq'; referenceNumber?: string};
}

export interface PosV2SaleResult {
  warehouseId: string;
  branchId: string;
  customerName: string;
  operationId: string;
  orderId: string;
  orderNumber: string;
  idempotentReplay: boolean;
  subtotalInMinorUnits: number;
  discountInMinorUnits: number;
  totalInMinorUnits: number;
  amountPaidInMinorUnits: number;
  changeDueInMinorUnits: number;
  paymentMethod: PaymentMethod;
  paymentStatus: 'paid' | 'unpaid' | 'partially_paid';
  initialPaymentMethod?: 'cash' | 'cliq';
  initialPaymentId?: string;
  remainingInMinorUnits?: number;
  items: unknown[];
}

export interface PosV2RecoveryInstruction {
  automaticRetry: false;
  reuseOriginalIdempotencyKey: true;
  rotateIdempotencyKey: false;
  verifyOutcomeBeforeRetry: true;
}

export type CreatePosSaleV2Outcome =
  | { ok: true; status: 'completed'; data: PosV2SaleResult }
  | {
      ok: false;
      status: 'rejected' | 'unknown';
      errorIdentity: string;
      message: string;
      rejectionCode?: string;
      recovery: PosV2RecoveryInstruction;
    };

export type PosV2RpcExecutor = (
  functionName: 'create_pos_sale_v2' | 'create_pos_sale_with_initial_payment_v1',
  parameters: Record<string, unknown>,
) => PromiseLike<{ data: unknown; error: { code?: string; message?: string } | null }>;

const recoveryInstruction: PosV2RecoveryInstruction = {
  automaticRetry: false,
  reuseOriginalIdempotencyKey: true,
  rotateIdempotencyKey: false,
  verifyOutcomeBeforeRetry: true,
};

const knownErrors: Record<string, string> = {
  POS216_INITIAL_PAYMENT_INVALID: 'راجع المدفوع الآن؛ يجب أن يكون أقل من صافي الفاتورة للدفع الجزئي.',
  POS216_SALE_CONTRACT_CHANGED: 'تغيّرت بيانات البيع؛ لم تُحفظ العملية. راجع السلة قبل المحاولة مجدداً.',
  PARCEL209_UNIT_SALE_FORBIDDEN:
    'هذا الصنف بيتباع بالطرد بس. احذف سطر المفرد وأضفه كطرد؛ لا تتغيّر السلة تلقائياً.',
  PARCEL209_FAMILY_CHANGED_RETRY:
    'تغيّرت نكهات المنتج. حدّث البيانات وراجع السلة قبل بدء محاولة جديدة.',
  PHASE3_IDEMPOTENCY_CONFLICT:
    'مفتاح إعادة المحاولة مرتبط بطلب مختلف. راجع البيع الموجود قبل أي محاولة جديدة.',
  CONFIGURABLE_PARCEL_DISABLED:
    'ميزة الطرود المخصصة غير مفعلة لهذا الحساب حاليًا.',
  PARCEL_CONFIGURATION_STALE:
    'تغير إعداد الطرد. أعد فتح المُنشئ وراجع التكوين الحالي.',
  PARCEL_CAPACITY_MISMATCH:
    'مجموع مكونات الطرد لا يساوي سعته المحددة.',
  PARCEL_COMPONENT_FAMILY_MISMATCH:
    'أحد مكونات الطرد لا ينتمي إلى العائلة التجارية المحددة.',
  PARCEL_COMPONENT_NOT_STOCKED:
    'أحد مكونات البيع لا يملك رصيدًا في المستودع.',
  PARCEL_COMPONENT_NOT_ALLOWED:
    'إحدى النكهات غير مسموحة في إعداد الطرد الحالي. أعد تركيب الطرد.',
  PHASE3_POS_INSUFFICIENT_INVENTORY:
    'المخزون المتاح لأحد مكونات البيع غير كافٍ.',
  PHASE3_POS_OPEN_SHIFT_REQUIRED:
    'افتح وردية الصندوق قبل إتمام البيع.',
};

const extractStableIdentity = (message: string | undefined): string | null => {
  const match = message?.match(/\b([A-Z][A-Z0-9_]{4,})\s*:/u);
  return match?.[1] || null;
};

const isAmbiguousTransportFailure = (
  error: { code?: string; message?: string } | null,
): boolean => {
  if (!error) return false;
  if (extractStableIdentity(error.message)) return false;
  return !error.code || /network|fetch|timeout|timed out|connection|abort/iu.test(
    error.message || '',
  );
};

const rpcParameters = (input: CreatePosSaleV2Input) => ({
  p_warehouse_id: input.warehouseId,
  p_branch_id: input.branchId,
  p_customer_id: input.customerId || null,
  p_customer_name: input.customerName?.trim() || 'زبون نقدي',
  p_payment_method: input.paymentMethod,
  p_lines: input.lines,
  p_discount_in_minor_units: input.discountInMinorUnits,
  p_amount_received_in_minor_units: input.amountReceivedInMinorUnits,
  p_idempotency_key: input.idempotencyKey,
});
const partialRpcParameters = (input: CreatePosSaleV2Input) => ({
  p_warehouse_id: input.warehouseId, p_branch_id: input.branchId,
  p_customer_id: input.customerId || null, p_customer_name: input.customerName?.trim() || 'زبون نقدي',
  p_lines: input.lines, p_discount_in_minor_units: input.discountInMinorUnits,
  p_initial_paid_in_minor_units: input.initialPayment!.amountInMinorUnits,
  p_initial_payment_method: input.initialPayment!.method,
  p_reference_number: input.initialPayment!.referenceNumber?.trim() || null,
  p_idempotency_key: input.idempotencyKey,
});

export async function submitPosSaleV2WithRpc(
  input: CreatePosSaleV2Input,
  executeRpc: PosV2RpcExecutor,
): Promise<CreatePosSaleV2Outcome> {
  input = structuredClone(input);
  if(input.initialPayment!==undefined&&!posV2RequestValid(input))return {
    ok:false,status:'rejected',errorIdentity:'POS216_INITIAL_PAYMENT_INVALID',rejectionCode:'22023',
    message:knownErrors.POS216_INITIAL_PAYMENT_INVALID,recovery:recoveryInstruction,
  };
  try {
    // Literal sinks keep the current RPC inventory independently auditable.
    const { data, error } = input.initialPayment
      ? await executeRpc('create_pos_sale_with_initial_payment_v1',partialRpcParameters(structuredClone(input)))
      : await executeRpc('create_pos_sale_v2',rpcParameters(structuredClone(input)));
    if (error) {
      const identity = extractStableIdentity(error.message);
      if (data != null || isAmbiguousTransportFailure(error)) {
        return {
          ok: false,
          status: 'unknown',
          errorIdentity: 'PHASE3_POS_WRITE_OUTCOME_UNKNOWN',
          message:
            'انقطع الاتصال بعد إرسال البيع. لا تعِد العملية بمفتاح جديد؛ تحقق من النتيجة أولًا.',
          recovery: recoveryInstruction,
        };
      }
      return {
        ok: false,
        status: 'rejected',
        rejectionCode: error.code,
        errorIdentity: identity || 'PHASE3_POS_REQUEST_REJECTED',
        message:
          (identity && knownErrors[identity]) ||
          'تعذر إتمام البيع. راجع البيانات ثم حاول بالمفتاح نفسه عند الحاجة.',
        recovery: recoveryInstruction,
      };
    }

    const payload = data as Partial<PosV2SaleResult> & { success?: boolean };
    if (!posV2ResultMatches(input, payload)) {
      return {
        ok: false,
        status: 'unknown',
        errorIdentity: 'PHASE3_POS_RESPONSE_INVALID',
        message:
          'وصل رد غير مكتمل بعد إرسال البيع. تحقق من النتيجة قبل إعادة المحاولة.',
        recovery: recoveryInstruction,
      };
    }
    return { ok: true, status: 'completed', data: payload as PosV2SaleResult };
  } catch {
    return {
      ok: false,
      status: 'unknown',
      errorIdentity: 'PHASE3_POS_WRITE_OUTCOME_UNKNOWN',
      message:
        'انقطع الاتصال بعد إرسال البيع. لا تعِد العملية بمفتاح جديد؛ تحقق من النتيجة أولًا.',
      recovery: recoveryInstruction,
    };
  }
}

export async function createPosSaleV2InSupabase(
  input: CreatePosSaleV2Input,
): Promise<CreatePosSaleV2Outcome> {
  const client = supabase;
  if (!isSupabaseConfigured || !client) {
    return {
      ok: false,
      status: 'rejected',
      errorIdentity: 'SUPABASE_NOT_CONFIGURED',
      message: 'الاتصال بقاعدة بيانات Supabase غير متاح.',
      recovery: recoveryInstruction,
    };
  }

  return submitPosSaleV2WithRpc(input, (functionName, parameters) =>
    client.rpc(functionName, parameters),
  );
}

