import type {Product} from '../../types';
import {MoneyText,ProductGlyph,UiButton} from '../../components/ui';
import type {PosSingleProductMode} from './saleMethods';

export function PosProductCard({product,stock,parcelQuantity,unitQuantity,disabled,onAdd,onReduce}:{
  product:Product;stock:number;parcelQuantity:number;unitQuantity:number;disabled:boolean;
  onAdd:(mode:PosSingleProductMode)=>void;onReduce:(mode:PosSingleProductMode)=>void;
}){
  const parcel=(product.unitsPerSalePackage??1)>1,unit=!product.parcelOnly;
  const methods=[...(parcel?[{mode:'legacy_single_sku_parcel' as const,label:'طرد',price:product.salePackagePrice,quantity:parcelQuantity}]:[]),
    ...(unit?[{mode:'base_unit' as const,label:'باكيت',price:product.retailPrice,quantity:unitQuantity}]:[])];
  return <article data-pos-product={product.id} className={'min-w-0 space-y-3 rounded-2xl border bg-nw-surface p-3 '+(parcelQuantity+unitQuantity>0?'border-nw-primary ring-1 ring-nw-primary':'border-nw-border')}>
    <div className="flex min-w-0 items-center gap-3">
      <ProductGlyph name={product.nameAr} image={product.imageUrl} className="h-14 w-14 shrink-0"/>
      <div className="min-w-0"><h3 className="break-words text-sm font-bold">{product.nameAr}</h3>
        <bdi dir="ltr" className="block break-all text-xs text-nw-muted">{product.barcode}</bdi>
        <p className={'text-xs '+(stock<=product.reorderLevel?'text-nw-warn':'text-nw-muted')}><bdi dir="ltr">{stock}</bdi> باكيت · {stock===0?'نفد':'متوفر'}</p>
      </div>
    </div>
    {product.parcelOnly&&<p className="text-xs font-bold text-nw-info">طرد فقط</p>}
    <div className="space-y-2">
      {methods.map((method,index)=>{
        const priceReady=typeof method.price==='number'&&Number.isFinite(method.price)&&method.price>=0;
        return <div key={method.mode} data-pos-sale-method={method.mode} className="grid min-w-0 grid-cols-[minmax(0,1fr)_auto_auto] items-center gap-2">
          <UiButton data-pos-product-card={index===0?product.id:undefined} data-pos-add-method={method.mode}
            aria-label={`إضافة ${method.label} من ${product.nameAr}`} disabled={disabled||!priceReady||stock<(method.mode==='base_unit'?1:product.unitsPerSalePackage??1)}
            onKeyDown={event=>{if(event.key==='Enter'&&event.repeat)event.preventDefault();}}
            onClick={()=>onAdd(method.mode)} className="min-w-0 flex-wrap justify-start px-2 text-xs">
            + {method.label} {priceReady?<MoneyText amount={method.price!}/>:<span>السعر غير متاح</span>}
          </UiButton>
          <output data-pos-product-quantity={index===0?product.id:undefined} data-pos-method-quantity={method.mode}
            aria-label={`عدد ${method.label} ${product.nameAr}`} className="nw-num min-w-5 text-center font-bold">{method.quantity}</output>
          <UiButton aria-label={`تقليل ${method.label} من ${product.nameAr}`} disabled={disabled||method.quantity===0}
            className="w-11 px-0" onClick={()=>onReduce(method.mode)}>−</UiButton>
        </div>;
      })}
    </div>
  </article>;
}

src/features/pos/PosParcelBuilder.tsx.beforeText:
import {useState} from 'react';
import {Modal} from '../../components/common/Modal';
import {UiButton} from '../../components/ui';
import type {PosV2ConfigurableParcelLine} from '../../services/supabase/posV2.service';

export interface PosParcelOption {
  familyProductId: string; nameAr: string; parcelConfigurationId: string;
  configurationRevision: number; unitsPerParcel: number; parcelPriceInMinorUnits: number;
  components: Array<{productId: string; nameAr: string; flavorNameAr?: string; sku: string; availableQuantity: number}>;
}
export function PosParcelBuilder({option, initialComponents, onClose, onAdd}: {option: PosParcelOption;
  initialComponents?: Array<{product_id: string; base_quantity: number}>;
  onClose: () => void; onAdd: (line: PosV2ConfigurableParcelLine) => void}) {
  const [quantities, setQuantities] = useState<Record<string, number>>(() => Object.fromEntries(
    (initialComponents || []).map(c => [c.product_id, c.base_quantity])));
  const total = Object.keys(quantities).reduce((sum, key) => sum + quantities[key], 0);
  const valid = total === option.unitsPerParcel
    && Object.keys(quantities).every(id => option.components.some(c => c.productId === id)) && option.components.every(c => {
    const q = quantities[c.productId] || 0;
    return Number.isSafeInteger(q) && q >= 0 && q <= c.availableQuantity;
  });
  return <Modal isOpen onClose={onClose} title={`تركيب طرد: ${option.nameAr}`}>
    <div className="space-y-4 p-4" data-unsaved={total > 0 ? 'true' : undefined}>
      <p role="status">المختار: {total} / {option.unitsPerParcel} باكيت — السعر {(option.parcelPriceInMinorUnits / 1000).toFixed(3)} د.أ</p>
      {option.components.map(c => <label key={c.productId} className="flex items-center justify-between gap-3">
        <span>{c.flavorNameAr || c.nameAr} <small>المتاح: {c.availableQuantity}</small></span>
        <input inputMode="numeric" enterKeyHint="next" type="number" min={0} max={c.availableQuantity} step={1} value={quantities[c.productId] || 0}
          aria-label={`كمية ${c.flavorNameAr || c.nameAr}`} className="min-h-11 w-20 rounded-xl border border-nw-border bg-nw-surface-2 p-2 text-nw-text"
          onChange={e => setQuantities(q => ({...q, [c.productId]: Number(e.target.value)}))}/>
      </label>)}
      <UiButton type="button" disabled={!valid} variant="primary"
        onClick={() => onAdd({commercial_line_kind: 'configurable_parcel', family_product_id: option.familyProductId,
          parcel_configuration_id: option.parcelConfigurationId, configuration_revision: option.configurationRevision,
          parcel_instances: [{components: option.components.filter(c => (quantities[c.productId] || 0) > 0)
            .map(c => ({product_id: c.productId, base_quantity: quantities[c.productId]}))}]})}>إضافة الطرد المكتمل</UiButton>
    </div>
  </Modal>;
}

src/features/pos/posV2Cart.ts.beforeText:
import type {Invoice, OrderItem, Product} from '../../types';
import type {PosV2Line, PosV2SaleResult} from '../../services/supabase/posV2.service';

export interface PosCartItem extends OrderItem {v2Line: PosV2Line; baseQuantity: number}
export function posCartLines(items: PosCartItem[]): PosV2Line[] {
  return items.map(item => item.v2Line.commercial_line_kind === 'base_unit'
    ? {...item.v2Line, base_quantity: item.quantity}
    : item.v2Line.commercial_line_kind === 'legacy_single_sku_parcel'
      ? {...item.v2Line, parcel_quantity: item.quantity} : structuredClone(item.v2Line));
}
export function posStockDemand(items: PosCartItem[]): Map<string, number> {
  const demand = new Map<string, number>();
  for (const line of posCartLines(items)) {
    const add = (id: string, q: number) => demand.set(id, (demand.get(id) || 0) + q);
    if (line.commercial_line_kind === 'base_unit') add(line.product_id, line.base_quantity);
    else if (line.commercial_line_kind === 'legacy_single_sku_parcel') add(line.product_id, line.parcel_quantity * line.units_per_parcel);
    else for (const p of line.parcel_instances) for (const c of p.components) add(c.product_id, c.base_quantity);
  }
  return demand;
}
export function posWarehouseAvailable(product: Product, warehouseId: string): number {
  const balance = product.warehouseBalances?.find(b => b.warehouseId === warehouseId);
  return balance ? balance.availableQuantity : product.warehouseId === warehouseId ? product.availableQuantity : 0;
}
export function receiptBaseUnitNames(value:unknown):ReadonlyMap<string,string>{
  const data=value&&typeof value==='object'?value as Record<string,unknown>:{};
  return new Map((Array.isArray(data.order_items)?data.order_items:[]).flatMap((row:unknown)=>{
    if(!row||typeof row!=='object')return [];const item=row as Record<string,unknown>;
    return typeof item.id==='string'&&typeof item.base_unit_name_snapshot==='string'&&item.base_unit_name_snapshot.trim()
      ?[[item.id,item.base_unit_name_snapshot.trim()] as const]:[];
  }));
}
export function posV2Invoice(sale: PosV2SaleResult, actor: {id: string; name: string}, createdAt: string,baseUnits:ReadonlyMap<string,string>=new Map()): Invoice & {changeDue: number} {
  const items = sale.items as Array<Record<string, any>>;
  return {id: sale.orderId, invoiceNumber: sale.orderNumber, orderId: sale.orderId, customerName: sale.customerName,
    items: items.map(i => ({id: i.id, productId: i.productId, productName: i.productName, sku: i.sku,
      productImage: '', unit: i.salePackage, unitPrice: i.unitPriceInMinorUnits / 1000,
      costPrice: i.cogsInMinorUnits / i.baseQuantity / 1000, quantity: i.quantity, baseQuantity: i.baseQuantity,
      unitsPerSalePackage: i.unitsPerSalePackage, salePackage: i.salePackage, discount: i.allocatedDiscountInMinorUnits / 1000,
      totalPrice: i.lineTotalInMinorUnits / 1000, commercialLineKind: i.commercialLineKind,
      ...(baseUnits.has(i.id)?{baseUnitName:baseUnits.get(i.id)}:{}),
      ...(Array.isArray(i.parcelInstances)&&i.parcelInstances.length?{parcelInstances:i.parcelInstances.map((p:Record<string,any>)=>({
        id:p.instance_id,sequence:p.instance_sequence,unitName:'طرد',
        components:(Array.isArray(p.components)?p.components:[]).map((c:Record<string,any>)=>({id:c.component_id,productId:c.product_id,
          name:c.product_name_snapshot,sku:c.sku_snapshot,unitName:c.base_unit_name_snapshot,quantity:c.base_quantity})),
      }))}:{})})),
    subtotal: sale.subtotalInMinorUnits / 1000, discount: sale.discountInMinorUnits / 1000, taxAmount: 0,
    totalAmount: sale.totalInMinorUnits / 1000, paidAmount: sale.amountPaidInMinorUnits / 1000,
    remainingAmount: (sale.totalInMinorUnits - sale.amountPaidInMinorUnits) / 1000, paymentMethod: sale.paymentMethod,
    ...(sale.initialPaymentMethod?{initialPaymentMethod:sale.initialPaymentMethod}:{}),
    status: 'posted', branchId: sale.branchId, createdById: actor.id, createdByName: actor.name, createdAt,
    changeDue: sale.changeDueInMinorUnits / 1000};
}

