        <nav
          aria-label="صفحات المنتجات"
          className="flex items-center justify-between rounded-2xl border border-nw-border bg-nw-surface px-3 py-2"
        >
          <UiButton variant="plain"
            type="button"
            onClick={() => setPage((value) => Math.max(1, value - 1))}
