/**
 * Nawasrah Business Manager - Modal Dispatcher & Sheet Center
 */

import React from 'react';
import {
  shallowEqual,
  useAppStoreActions,
  useAppStoreSelector,
} from '../../stores/useAppStore';
import {
  isOrderModalPayload,
  isProductIdModalPayload,
  isProductModalPayload,
  isStockAdjustmentModalPayload,
} from '../../stores/modalTypes';
import { Modal } from '../common/Modal';
import { ProductFormModal } from '../../features/products/ProductFormModal';
import { ProductDetailModal } from '../../features/products/ProductDetailModal';
import { StockAdjustmentModal } from '../../features/products/StockAdjustmentModal';
import {DamageProductSelection} from '../../features/more/DamageProductSelection';
import {SupplierReplacementPanel} from '../../features/inventory/SupplierReplacementPanel';
import { CategoriesModal } from './CategoriesModal';
import { BrandsModal } from './BrandsModal';
import { UnitsModal } from './UnitsModal';
import { ProfileModal } from '../../features/more/ProfileModal';
import { OrderDetailModal } from '../../features/orders/OrderDetailModal';
import { CreateDirectReceiptModal } from '../../features/directReceiving/CreateDirectReceiptModal';
import { WarehouseTransferModal } from '../../features/inventory/WarehouseTransferModal';
import { StockCountModal } from '../../features/inventory/StockCountModal';
import { InventoryOpeningSetupModal } from '../../features/inventory/InventoryOpeningSetupModal';
import { RecordCustomerPaymentModal } from '../../features/accounts/RecordCustomerPaymentModal';
import { AddCustomerModalContent } from '../../features/crm/AddCustomerModalContent';
import { PromotionCodesModal } from '../../features/more/PromotionCodesModal';
import {PushNotificationControls} from '../../features/more/PushNotificationControls';
import { StorefrontSettingsModal } from '../../features/more/StorefrontSettingsModal';
import { ParcelConfigurationModal } from '../../features/more/ParcelConfigurationModal';
import { ExpenseFormModal } from '../../features/expenses/ExpenseFormModal';
import { MonitoringDashboardModal } from '../../features/more/MonitoringDashboardModal';
import {
  CheckCheck,
  PackageOpen,
} from 'lucide-react';

export const AllModals: React.FC = () => {
  const {
    currentModal,
    modalData,
    notifications,
  } = useAppStoreSelector(
    (state) => ({
      currentModal: state.currentModal,
      modalData: state.modalData,
      notifications: state.notifications,
    }),
    shallowEqual
  );
  const { closeModal, markNotificationRead, markAllNotificationsRead } =
    useAppStoreActions();
  const productFormInitialProduct =
    currentModal === 'edit_product' && isProductModalPayload(modalData)
      ? modalData
      : null;
  const warehouseTransferProductId =
    currentModal === 'warehouse_transfer' &&
    isProductIdModalPayload(modalData)
      ? modalData.productId
      : undefined;
  const stockCountProductId =
    currentModal === 'stock_count' && isProductIdModalPayload(modalData)
      ? modalData.productId
      : undefined;
  const receiveGoodsProductId =
    currentModal === 'receive_goods' && isProductIdModalPayload(modalData)
      ? modalData.productId
      : undefined;

  return (
    <>
      {/* 1. Add / Edit Product Modal */}
      <Modal
        isOpen={currentModal === 'add_product' || currentModal === 'edit_product'}
        onClose={closeModal}
        title={currentModal === 'edit_product' ? 'تعديل بطاقة المنتج' : 'إضافة منتج جديد'}
        subtitle="عرّف طرد الشراء وطرد بيع الجملة وحدود المخزون"
      >
        <ProductFormModal initialProduct={productFormInitialProduct} onClose={closeModal} />
      </Modal>

      {/* 2. View Product Details Modal */}
      <Modal
        isOpen={currentModal === 'view_product' && isProductModalPayload(modalData)}
        onClose={closeModal}
        title="تفاصيل الصنف والمخزون"
        subtitle="عرض الأسعار والكميات والمستودع"
      >
        {currentModal === 'view_product' && isProductModalPayload(modalData) && (
          <ProductDetailModal product={modalData} onClose={closeModal} />
        )}
      </Modal>

      <Modal isOpen={currentModal==='damage_stock_selection'} onClose={closeModal} title="اختر الصنف التالف" subtitle="ثم سجل الكمية والسبب في نموذج تعديل المخزون" trackChanges={false}><DamageProductSelection/></Modal>

      {/* 3. Adjust Stock Modal */}
      <Modal
        isOpen={
          currentModal === 'adjust_stock' &&
          isStockAdjustmentModalPayload(modalData)
        }
        onClose={closeModal}
        title="تعديل وتسوية المخزون"
        subtitle="إضافة أو خصم كمية مع تسجيل سبب الحركة"
      >
        {currentModal === 'adjust_stock' &&
          isStockAdjustmentModalPayload(modalData) && (
          <StockAdjustmentModal
            product={modalData.product}
            mode={modalData.mode || 'add'}
            onClose={closeModal}
          />
          )}
      </Modal>

      {/* Standalone Direct Receive Goods Modal */}
      <Modal
        isOpen={currentModal === 'receive_goods'}
        onClose={closeModal}
        title="استلام بضاعة"
        subtitle="اختر المورد والصنف وعدد الطرود ثم احفظ"
      >
        <CreateDirectReceiptModal
          onClose={closeModal}
          initialProductId={receiveGoodsProductId}
        />
      </Modal>

      {/* Warehouse Transfer Modal */}
      <Modal
        isOpen={currentModal === 'warehouse_transfer'}
        onClose={closeModal}
        title="نقل كميات بين المستودعات"
        subtitle="تحويل بضاعة من مستودع إلى آخر مع تسجيل حركات الخروج والدخول"
      >
        <WarehouseTransferModal productId={warehouseTransferProductId} onClose={closeModal} />
      </Modal>

      {/* Stock Count / Audit Modal */}
      <Modal
        isOpen={currentModal === 'stock_count'}
        onClose={closeModal}
        title="جرد صنف"
        subtitle="أدخل الكمية الفعلية، والنظام يحفظ الفرق تلقائيًا"
      >
        <StockCountModal productId={stockCountProductId} onClose={closeModal} />
      </Modal>

      {/* 4. Manage Categories Modal */}
      <Modal
        isOpen={currentModal === 'manage_categories'}
        onClose={closeModal}
        title="إدارة الأقسام والكتالوج"
        subtitle="أضف الأقسام التي تناسب بضاعتكم وأدر ظهورها بأمان"
      >
        <CategoriesModal onClose={closeModal} />
      </Modal>

      {/* 5. Manage Brands Modal */}
      <Modal
        isOpen={currentModal === 'manage_brands'}
        onClose={closeModal}
        title="إدارة العلامات التجارية"
        subtitle="إضافة وتعديل العلامات التجارية والشعارات"
      >
        <BrandsModal onClose={closeModal} />
      </Modal>

      {/* 6. Manage Units Modal */}
      <Modal
        isOpen={currentModal === 'manage_units'}
        onClose={closeModal}
        title="إدارة وحدات القياس والتعبئة"
        subtitle="تعريف ووحدات التعبئة والمعاملات"
      >
        <UnitsModal onClose={closeModal} />
      </Modal>

      {/* 7. Profile Settings Modal */}
      <Modal
        isOpen={currentModal === 'profile' || currentModal === 'profile_settings'}
        onClose={closeModal}
        title="الملف الشخصي وإعدادات الحساب"
        subtitle="إدارة بياناتك الشخصية، الأمان، الجلسات النشطة والإشعارات"
      >
        <ProfileModal onClose={closeModal} />
      </Modal>

      {/* 8. Add / Edit User Modal */}
      <Modal
        isOpen={currentModal === 'storefront_settings'}
        onClose={closeModal}
        title="إدارة المتجر الإلكتروني"
        subtitle="إعدادات واحدة بسيطة تتحكم بالموقع وطلبات العملاء مباشرة"
      >
        <StorefrontSettingsModal />
      </Modal>

      {/* Bulk opening inventory setup */}
      <Modal isOpen={currentModal==='supplier_replacement'} onClose={closeModal} title="استبدال المورد والتالف" maxWidth="max-w-2xl">
        {currentModal==='supplier_replacement'&&<SupplierReplacementPanel {...(modalData&&'damageOnly' in modalData?modalData:modalData&&'supplierId' in modalData?modalData:modalData&&'productId' in modalData?{productId:modalData.productId}:{})}/>}
      </Modal>
      <Modal isOpen={currentModal === 'parcel_configuration'} onClose={closeModal}
        title="الطرد المشكّل (خلط النكهات)" subtitle="النكهات وكم حبة بالطرد — للمالك فقط">
        <ParcelConfigurationModal initialFamilyProductId={modalData&&'familyProductId' in modalData?modalData.familyProductId:undefined}/>
      </Modal>

      <Modal
        isOpen={currentModal === 'inventory_opening_setup'}
        onClose={closeModal}
        title="تهيئة المخزون الافتتاحي"
        subtitle="إدخال البضاعة الموجودة فعليًا قبل بدء التشغيل دون إنشاء مديونية مورد"
        maxHeight="max-h-[96vh]"
        maxWidth="max-w-5xl"
      >
        <InventoryOpeningSetupModal onClose={closeModal} />
      </Modal>

      {/* Promotion codes */}
      <Modal
        isOpen={currentModal === 'promotion_codes'}
        onClose={closeModal}
        title="رموز الخصم للموقع"
        subtitle="إنشاء الرموز ومتابعة الاستخدام وإيقافها مع حفظ السجل"
      >
        <PromotionCodesModal />
      </Modal>

      {/* 9. View Order Details Modal */}
      <Modal
        isOpen={currentModal === 'view_order' && isOrderModalPayload(modalData)}
        onClose={closeModal}
        title="تفاصيل الطلب والتحصيل"
        subtitle="متابعة حالة الطلب وقبوله وتعيين السائق"
      >
        {currentModal === 'view_order' && isOrderModalPayload(modalData) && (
          <OrderDetailModal order={modalData} onClose={closeModal} />
        )}
      </Modal>

      {/* 10. Add Expense Modal */}
      <Modal
        isOpen={currentModal === 'add_expense'}
        onClose={closeModal}
        title="تسجيل مصروف تشغيلي"
        subtitle="وثّق الإيجار أو الرواتب أو الفواتير"
      >
        <ExpenseFormModal onClose={closeModal} />
      </Modal>

      {/* 11. Customer Payment Modal */}
      <Modal
        isOpen={currentModal === 'record_customer_payment'}
        onClose={closeModal}
        title="تسجيل دفعة عميل (سند قبض)"
        subtitle="ربط الدفعة بطلب مكتمل وتحديث الذمة تلقائياً"
      >
        <RecordCustomerPaymentModal onClose={closeModal} />
      </Modal>

      {/* 13. Notifications Drawer */}
      <Modal
        isOpen={currentModal === 'notifications'}
        onClose={closeModal}
        title="مركز الإشعارات والتنبيهات"
        subtitle="جميع الإشعارات القادمة من المتجر أونلاين والمخزون"
      >
        <div className="space-y-3 text-xs">
          <PushNotificationControls />

          <div className="flex items-center justify-between gap-2">
            {notifications.some((notification) => !notification.read) && (
              <button
                type="button"
                onClick={() => markAllNotificationsRead()}
                className="flex items-center gap-1.5 rounded-xl border border-nw-border bg-nw-surface-2 px-3 py-2 font-bold text-nw-text transition hover:bg-nw-track"
              >
                <CheckCheck className="h-3.5 w-3.5" />
                تحديد الكل كمقروء
              </button>
            )}
          </div>

          {notifications.length === 0 ? (
            <div className="rounded-2xl border border-nw-border bg-nw-surface p-7 text-center">
              <PackageOpen className="mx-auto mb-2 h-8 w-8 text-nw-ok" />
              <h4 className="font-extrabold text-nw-text">
                المخزون بحالة جيدة
              </h4>
              <p className="mt-1 text-[11px] text-nw-muted">
                سيظهر هنا أي منتج يصل إلى حد التنبيه المحدد.
              </p>
            </div>
          ) : (
            notifications.map((notification) => (
              <button
                type="button"
                key={notification.id}
                onClick={() => markNotificationRead(notification.id)}
                className={`w-full space-y-1 rounded-xl border p-3 text-right transition ${
                  notification.read
                    ? 'border-nw-border bg-nw-surface opacity-75'
