import type { SupabaseClient } from '@supabase/supabase-js';

type Action = 'cancel' | 'complete';
type AttemptStatus = 'PREPARED' | 'IN_FLIGHT' | 'SUCCEEDED' |
  'DEFINITIVELY_REJECTED' | 'OUTCOME_UNKNOWN';

interface LegacyPendingAction {
  version: 1; actorId: string; orderId: string; action: Action;
  key: string; request: Record<string, unknown>;
}
interface LifecycleAttempt {
  version: 2; actorId: string; orderId: string; action: Action;
  attemptId: string; key: string; request: Record<string, unknown>;
  status: AttemptStatus; executionGeneration: number; hadUnknownOutcome: boolean;
  result?: Record<string, unknown>; errorIdentity?: string; rejectionCode?: 'P0001';
}

const pendingPrefix = 'nawasrah:admin:customer-v2-lifecycle:v1:';
const adminActionLockWaitMs = 5_000;
const definitiveRejections: Record<Action, ReadonlySet<string>> = {
  complete: new Set([
    'PHASE3_CUSTOMER_SETTLEMENT_INVALID',
    'PHASE3_CUSTOMER_ORDER_NOT_FOUND', 'PHASE3_CUSTOMER_LIFECYCLE_CONTRACT_MISMATCH',
    'PHASE3_CUSTOMER_LIFECYCLE_INVALID', 'PHASE3_CUSTOMER_OPEN_SHIFT_REQUIRED',
    'PHASE3_CUSTOMER_RESERVATION_TERMINAL', 'PHASE3_CUSTOMER_RESERVATION_MISMATCH',
    'PHASE3_EXACT_WAC_UNAVAILABLE',
  ]),
  cancel: new Set([
    'PHASE3_CUSTOMER_LIFECYCLE_CONTRACT_MISMATCH',
    'PHASE3_CUSTOMER_LIFECYCLE_INVALID', 'PHASE3_CUSTOMER_RESERVATION_TERMINAL',
    'PHASE3_CUSTOMER_RESERVATION_MISMATCH',
  ]),
};

const canonicalize = (value: unknown): unknown => {
  if (Array.isArray(value)) return value.map(canonicalize);
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value as Record<string, unknown>)
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([key, entry]) => [key, canonicalize(entry)]));
  }
  return value;
};
const sameRequest = (left: Record<string, unknown>, right: Record<string, unknown>) =>
  JSON.stringify(canonicalize(left)) === JSON.stringify(canonicalize(right));
const extractIdentity = (message: unknown): string | null => typeof message === 'string'
  ? message.match(/^([A-Z][A-Z0-9_]{4,}):/u)?.[1] || null : null;
const isObject = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const isAction = (value: unknown): value is Action => value === 'complete' || value === 'cancel';
const isStatus = (value: unknown): value is AttemptStatus => typeof value === 'string' && [
  'PREPARED', 'IN_FLIGHT', 'SUCCEEDED', 'DEFINITIVELY_REJECTED', 'OUTCOME_UNKNOWN',
].includes(value);
const isLegacyAttempt = (value: unknown): value is LegacyPendingAction => isObject(value)
  && value.version === 1 && typeof value.actorId === 'string'
  && typeof value.orderId === 'string' && isAction(value.action)
  && typeof value.key === 'string' && isObject(value.request);
const isCurrentAttempt = (value: unknown): value is LifecycleAttempt => isObject(value)
  && value.version === 2 && typeof value.actorId === 'string'
  && typeof value.orderId === 'string' && isAction(value.action)
  && typeof value.attemptId === 'string' && typeof value.key === 'string'
  && isObject(value.request) && isStatus(value.status)
  && Number.isSafeInteger(value.executionGeneration) && Number(value.executionGeneration) >= 0
  && typeof value.hadUnknownOutcome === 'boolean'
  && (value.result === undefined || isObject(value.result))
  && (value.errorIdentity === undefined || typeof value.errorIdentity === 'string');

const newAttemptId = (): string => {
  if (typeof crypto?.randomUUID !== 'function') {
    throw new Error('لا يمكن إنشاء هوية محاولة آمنة. لا تبدأ العملية.');
  }
  return crypto.randomUUID();
};
async function actionKey(actorId: string, orderId: string, action: Action, attemptId: string) {
  const encoded = new TextEncoder().encode(
    `admin-customer-v2:v2:${actorId}:${orderId}:${action}:${attemptId}`,
  );
  const digest = await crypto.subtle.digest('SHA-256', encoded);
  return `admin-v2:${Array.from(new Uint8Array(digest), (byte) =>
    byte.toString(16).padStart(2, '0')).join('')}`;
}
const persist = (storageKey: string, attempt: LifecycleAttempt): void => {
  const encoded = JSON.stringify(attempt);
  localStorage.setItem(storageKey, encoded);
  if (localStorage.getItem(storageKey) !== encoded) throw new Error('تعذر تثبيت حالة محاولة الطلب.');
};
const minorUnits = (value: unknown): value is number =>
  typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
const nullableText = (value: unknown) => value === null || typeof value === 'string';
const requestIsValid = (action: Action, value: Record<string, unknown>) => action === 'cancel'
  ? Object.keys(value).length === 1 && nullableText(value.reason)
  : Object.keys(value).length === 5 && typeof value.paymentMethod === 'string'
    && ['cash', 'cliq', 'debt'].includes(value.paymentMethod)
    && minorUnits(value.amountCollectedInMinorUnits) && minorUnits(value.deliveryFeeInMinorUnits)
    && nullableText(value.referenceNumber) && nullableText(value.notes);
const responseIsSuccess = (action: Action, orderId: string, value: unknown):
  value is Record<string, unknown> => {
  if (!isObject(value) || value.success !== true || value.order_id !== orderId
    || typeof value.operation_id !== 'string'
    || !/^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/iu.test(value.operation_id)
    || value.status !== (action === 'complete' ? 'completed' : 'cancelled')) return false;
  if (action === 'cancel') return value.reservation_state === 'cancelled'
    && minorUnits(value.released_reservations);
  if (!minorUnits(value.total_in_minor_units) || !minorUnits(value.amount_paid_in_minor_units)
    || !minorUnits(value.remaining_in_minor_units)) return false;
  return value.total_in_minor_units - value.amount_paid_in_minor_units === value.remaining_in_minor_units
    && value.payment_status === (value.remaining_in_minor_units === 0 ? 'paid'
      : value.amount_paid_in_minor_units > 0 ? 'partially_paid' : 'unpaid')
    && (value.remaining_in_minor_units > 0 || value.amount_paid_in_minor_units === 0
      ? value.payment_method === 'debt' : typeof value.payment_method === 'string'
        && ['cash', 'cliq'].includes(value.payment_method))
    && nullableText(value.customer_payment_number);
};
const reviewRequired = () => new Error(
  'ADMIN_LIFECYCLE_REVIEW_REQUIRED: تغيرت محاولة الطلب أو أدلتها غير متطابقة. راجع حالة الطلب قبل أي إجراء جديد.',
);
// One state/identity boundary for initial reads, post-RPC reads and every write.
async function validateAttempt(value: unknown, actorId: string, orderId: string, action: Action):
Promise<LifecycleAttempt> {
  if (!isCurrentAttempt(value) || value.actorId !== actorId || value.orderId !== orderId
    || value.action !== action || !value.attemptId || !requestIsValid(action, value.request)
    || value.key !== await actionKey(actorId, orderId, action, value.attemptId)) throw reviewRequired();
  const noResult = value.result === undefined;
  switch (value.status) {
    case 'PREPARED':
      if (value.executionGeneration !== 0 || value.hadUnknownOutcome || !noResult
        || value.errorIdentity !== undefined) throw reviewRequired();
      break;
    case 'DEFINITIVELY_REJECTED':
      if (value.executionGeneration < 1 || value.hadUnknownOutcome || !noResult
        || value.rejectionCode !== 'P0001'
        || !value.errorIdentity || !definitiveRejections[action].has(value.errorIdentity)) throw reviewRequired();
      break;
    case 'SUCCEEDED':
      if (value.executionGeneration < 1 || value.errorIdentity !== undefined
        || !responseIsSuccess(action, orderId, value.result)) throw reviewRequired();
      if (action === 'complete' && value.result!.amount_paid_in_minor_units !==
        (value.request.paymentMethod === 'debt' ? 0 : value.request.amountCollectedInMinorUnits)) throw reviewRequired();
      if (action === 'complete' && value.result!.payment_method !==
        (Number(value.result!.remaining_in_minor_units) > 0 || value.result!.amount_paid_in_minor_units === 0
          ? 'debt' : value.request.paymentMethod)) throw reviewRequired();
      break;
    case 'OUTCOME_UNKNOWN':
      if (value.executionGeneration < 1 || !value.hadUnknownOutcome || !noResult) throw reviewRequired();
      break;
    case 'IN_FLIGHT':
      if (value.executionGeneration < 1 || !noResult) throw reviewRequired();
  }
  if (value.status !== 'DEFINITIVELY_REJECTED' && value.rejectionCode !== undefined) throw reviewRequired();
  return value;
}
const sameImmutableIdentity = (left: LifecycleAttempt, right: LifecycleAttempt) =>
  left.actorId === right.actorId && left.orderId === right.orderId && left.action === right.action
  && left.attemptId === right.attemptId && left.key === right.key
  && sameRequest(left.request, right.request);
const sameIdentity = (left: LifecycleAttempt, right: LifecycleAttempt) =>
  sameImmutableIdentity(left, right) && left.executionGeneration === right.executionGeneration;
async function readAttempt(storageKey: string, expected: LifecycleAttempt) {
  const raw = localStorage.getItem(storageKey);
  const fresh = await validateAttempt(raw === null ? null : JSON.parse(raw),
    expected.actorId, expected.orderId, expected.action);
  const completedSameAttempt = fresh.status === 'SUCCEEDED' && sameImmutableIdentity(fresh, expected)
    && fresh.executionGeneration <= expected.executionGeneration;
  if (localStorage.getItem(storageKey) !== raw || (!completedSameAttempt && (!sameIdentity(fresh, expected)
    || (expected.hadUnknownOutcome && !fresh.hadUnknownOutcome)))) throw reviewRequired();
  return {fresh, raw};
}
async function writeAttempt(storageKey: string, value: LifecycleAttempt, expectedRaw: string | null,
  retryDecision = false) {
  await validateAttempt(value, value.actorId, value.orderId, value.action);
  if (localStorage.getItem(storageKey) !== expectedRaw) {
    if (retryDecision) return false;
    throw reviewRequired();
  }
  persist(storageKey, value);
  return true;
}
const sameCommercialResult = (action: Action, left: Record<string, unknown>, right: Record<string, unknown>) => {
  const fields = action === 'cancel'
    ? ['order_id', 'operation_id', 'status', 'reservation_state', 'released_reservations']
    : ['order_id', 'operation_id', 'status', 'payment_method', 'payment_status',
      'total_in_minor_units', 'amount_paid_in_minor_units', 'remaining_in_minor_units', 'customer_payment_number'];
  return fields.every((field) => left[field] === right[field]);
};
const invalidResponse = () => ({
  code: 'ADMIN_LIFECYCLE_RESPONSE_INVALID',
  message: 'ADMIN_LIFECYCLE_RESPONSE_INVALID: وصل رد غير مكتمل. تحقق من حالة الطلب قبل المحاولة مجددًا.',
});
const lockWaitTimedOut = () => new Error(
  'ADMIN_LIFECYCLE_LOCK_WAIT_TIMEOUT: عملية أخرى ما زالت قيد التنفيذ أو التعافي. لم تبدأ محاولة جديدة؛ انتظر قليلًا ثم أعد المحاولة بنفس البيانات.',
);
const lockUnsupported = () => new Error(
  'ADMIN_LIFECYCLE_LOCK_UNSUPPORTED: المتصفح لا يوفر تنسيقًا آمنًا لانتظار العملية. استخدم متصفحًا محدثًا.',
);
export async function withAdminActionLock<T>(
  lockName: string, work: () => Promise<T>, waitMs = adminActionLockWaitMs,
): Promise<T> {
  const manager = globalThis.navigator?.locks;
  if (!manager || typeof AbortController !== 'function') throw lockUnsupported();
  const controller = new AbortController();
  let granted = false;
  const timer = globalThis.setTimeout(() => controller.abort(), waitMs);
  try {
    return await manager.request(lockName, {signal: controller.signal}, async () => {
      granted = true;
      globalThis.clearTimeout(timer);
      return work();
    });
  } catch (error) {
    if (!granted && controller.signal.aborted) throw lockWaitTimedOut();
    if (!granted && ((error instanceof DOMException && error.name === 'NotSupportedError')
      || error instanceof TypeError)) throw lockUnsupported();
    throw error;
  } finally {
    globalThis.clearTimeout(timer);
  }
}

// The operation type, not the presence of parcel rows, identifies Customer V2.
export async function isCustomerV2Order(client: SupabaseClient, orderId: string): Promise<boolean> {
  const orderResult = await client.from('orders').select('operation_id').eq('id', orderId).single();
  if (orderResult.error || !orderResult.data) {
    throw new Error(orderResult.error?.message || 'تعذر تحديد نوع الطلب.');
  }
  const operationId = orderResult.data.operation_id;
  if (!operationId) return false;
  const operationResult = await client.from('business_operations')
    .select('operation_type').eq('id', operationId).single();
  if (operationResult.error || !operationResult.data) {
    throw new Error(operationResult.error?.message || 'تعذر تحديد عقد العملية الأصلية.');
  }
  return operationResult.data.operation_type === 'phase3_customer_reservation_v1';
}

export async function runCustomerV2AdminAction(
  client: SupabaseClient, orderId: string, action: Action, request: Record<string, unknown>,
): Promise<{ data: any; error: any }> {
  // Capture the submitted request before the first await; callers cannot mutate it in flight.
  if (!isAction(action) || !requestIsValid(action, request)) throw reviewRequired();
  request = structuredClone(request);
  const auth = await client.auth.getUser();
  const actorId = auth.data.user?.id;
  if (auth.error || !actorId) throw new Error('تعذر التحقق من المستخدم الحالي. أعد تسجيل الدخول.');
  if (typeof localStorage === 'undefined') throw new Error('لا يمكن حفظ هوية المحاولة محليًا. لا تبدأ العملية.');
  const storageKey = `${pendingPrefix}${actorId}:${orderId}:${action}`;
  const lockName = `${pendingPrefix}lock:${actorId}:${orderId}:${action}`;

  return withAdminActionLock(lockName, async () => {
    const lockedAuth = await client.auth.getUser();
    if (lockedAuth.error || lockedAuth.data.user?.id !== actorId) throw reviewRequired();
    let attempt!: LifecycleAttempt;
    try {
      let previousObservation: LifecycleAttempt | null | undefined;
      // Bounded decision refresh only, with unchanged immutable identity. This
      // handles localStorage propagation after Web Lock handoff, not RPC retry.
      for (let decision = 0; decision < 3; decision += 1) {
        const raw = localStorage.getItem(storageKey);
        let existing: LifecycleAttempt | null = null;
        if (raw === null) {
          const attemptId = newAttemptId();
          attempt = {version: 2, actorId, orderId, action, attemptId,
            key: await actionKey(actorId, orderId, action, attemptId), request,
            status: 'PREPARED', executionGeneration: 0, hadUnknownOutcome: false};
        } else {
          const parsed: unknown = JSON.parse(raw);
          if (isLegacyAttempt(parsed)) {
            if (parsed.actorId !== actorId || parsed.orderId !== orderId || parsed.action !== action
              || !sameRequest(parsed.request, request)) {
              throw new Error('المحاولة القديمة لا تملك دليل نتيجة كافيًا. راجع حالة الطلب قبل أي إجراء جديد.');
            }
            // The retained V1 record does not prove how its key was derived.
            // Preserve its bytes rather than minting V2 evidence from a guess.
            throw new Error('المحاولة القديمة لا تملك دليل هوية كافيًا. راجع حالة الطلب قبل أي إجراء جديد.');
          } else {
            attempt = await validateAttempt(parsed, actorId, orderId, action);
            existing = structuredClone(attempt);
          }
        }
        if (previousObservation !== undefined && (existing === null
          ? previousObservation !== null
          : previousObservation === null || !sameIdentity(existing, previousObservation))) throw reviewRequired();
        if (localStorage.getItem(storageKey) !== raw) {
          if (decision === 2) throw reviewRequired();
          previousObservation = existing;
          continue;
        }

        if (attempt.status === 'SUCCEEDED') {
          if (!sameRequest(attempt.request, request) || !responseIsSuccess(action, orderId, attempt.result)) {
            throw new Error('الطلب ناجح سابقًا لكن دليل النتيجة غير متطابق. راجع حالة الطلب.');
          }
          return {data: attempt.result, error: null};
        }
        if (attempt.status === 'OUTCOME_UNKNOWN' || attempt.status === 'IN_FLIGHT') {
          if (!sameRequest(attempt.request, request)) {
            throw new Error('نتيجة المحاولة السابقة غير محسومة. لا تغيّر المدخلات أو مفتاح المحاولة.');
          }
          attempt.hadUnknownOutcome = true;
        } else if (attempt.status === 'DEFINITIVELY_REJECTED') {
          const attemptId = newAttemptId();
          attempt = {version: 2, actorId, orderId, action, attemptId,
            key: await actionKey(actorId, orderId, action, attemptId), request,
            status: 'PREPARED', executionGeneration: 0, hadUnknownOutcome: false};
        } else if (!sameRequest(attempt.request, request)) {
          throw new Error('توجد محاولة جارية بمدخلات مختلفة. انتظر نتيجتها أولًا.');
        }

        const executionGeneration = attempt.executionGeneration + 1;
        attempt = {...attempt, status: 'IN_FLIGHT', executionGeneration, rejectionCode: undefined};
        if (!await writeAttempt(storageKey, attempt, raw, true)) {
          if (decision === 2) throw reviewRequired();
          previousObservation = existing;
          continue;
        }
        break;
      }
      let result: {data: any; error: any};
      try {
        result = action === 'cancel'
          ? await client.rpc('cancel_customer_order_v2', {p_order_id: orderId,
            p_idempotency_key: attempt.key, p_reason: attempt.request.reason})
          : await client.rpc('complete_website_order_with_settlement_v2', {p_order_id: orderId,
            p_idempotency_key: attempt.key, p_payment_method: attempt.request.paymentMethod,
            p_amount_collected_in_minor_units: attempt.request.amountCollectedInMinorUnits,
            p_delivery_fee_in_minor_units: attempt.request.deliveryFeeInMinorUnits,
            p_reference_number: attempt.request.referenceNumber, p_notes: attempt.request.notes});
      } catch (error) {
        const {fresh, raw: freshRaw} = await readAttempt(storageKey, attempt);
        if (fresh.status === 'SUCCEEDED') return {data: fresh.result, error: null};
        if (fresh.status !== 'IN_FLIGHT') throw reviewRequired();
        await writeAttempt(storageKey, {...fresh, status: 'OUTCOME_UNKNOWN', hadUnknownOutcome: true}, freshRaw);
        throw error;
      }

      const {fresh, raw: freshRaw} = await readAttempt(storageKey, attempt);
      if (fresh.status === 'SUCCEEDED') {
        if (!result.error && responseIsSuccess(action, orderId, result.data)
          && !sameCommercialResult(action, fresh.result!, result.data)) throw reviewRequired();
        return {data: fresh.result, error: null};
      }
      if (fresh.status !== 'IN_FLIGHT') throw reviewRequired();
      if (!result.error && responseIsSuccess(action, orderId, result.data)) {
        await writeAttempt(storageKey, {...fresh, status: 'SUCCEEDED', result: result.data,
          errorIdentity: undefined}, freshRaw);
        return result;
      }
      if (result.error) {
        const identity = extractIdentity(result.error.message);
        const canReject = !fresh.hadUnknownOutcome && result.data === null && result.error.code === 'P0001'
          && identity !== null
          && definitiveRejections[action].has(identity);
        await writeAttempt(storageKey, {...fresh,
          status: canReject ? 'DEFINITIVELY_REJECTED' : 'OUTCOME_UNKNOWN',
          hadUnknownOutcome: fresh.hadUnknownOutcome || !canReject,
          errorIdentity: identity || undefined, rejectionCode: canReject ? 'P0001' : undefined}, freshRaw);
        return result;
      }
      await writeAttempt(storageKey, {...fresh, status: 'OUTCOME_UNKNOWN', hadUnknownOutcome: true,
        errorIdentity: 'ADMIN_LIFECYCLE_RESPONSE_INVALID'}, freshRaw);
      return {data: result.data, error: invalidResponse()};
    } catch (error) {
      throw new Error(error instanceof Error ? error.message :
        'تعذر قراءة محاولة الطلب السابقة بأمان.', {cause: error});
    }
  });
}

src/services/supabase/orders.service.ts.beforeText:
import {safeGoogleMapsUrl, validMapCoordinates} from '../../utils/googleMaps';
import { supabase, isSupabaseConfigured } from '../../lib/supabase';
import { Order, OrderStatus, PaymentMethod, PaymentStatus } from '../../types';
import { isCustomerV2Order, runCustomerV2AdminAction } from './adminCustomerV2Lifecycle';
import { attachHistoricalParcelComposition } from './historicalParcelComposition';
import {storefrontReceiptUrl} from './pos.service';
import {orderExchangeFunding} from '../../utils/orderExchangeFunding';
import {
  calculateOrderAmountDue,
  type OperationalOrderFilter,
} from '../../utils/orderCalculations';

const paymentMethods: PaymentMethod[] = [
  'cash',
  'cash_on_delivery',
  'cliq',
  'card',
  'bank_transfer',
  'debt',
  'mixed',
  'exchange_credit',
];
const paymentStatuses: PaymentStatus[] = ['unpaid', 'partially_paid', 'paid', 'refunded'];

export type OperationalOrdersSort = 'newest' | 'oldest';

export interface OperationalOrdersPageInput {
  page: number;
  pageSize: number;
  filter: OperationalOrderFilter;
  searchQuery?: string;
  sort?: OperationalOrdersSort;
}

export interface OperationalOrdersSummary {
  review: number;
  active: number;
  due: number;
}

export interface OperationalOrdersPage {
  success: boolean;
  orders: OperationalOrderListItem[];
  page: number;
  pageSize: number;
  totalCount: number;
  totalPages: number;
  summary: OperationalOrdersSummary;
  error?: string;
}

export interface OperationalOrderListItem {
  id: string;
  orderNumber: string;
  customerName: string;
  customerPhone: string;
  governorate: string;
  region: string;
  status: OrderStatus;
  paymentMethod: PaymentMethod;
  paymentStatus: PaymentStatus;
  totalAmount: number;
  amountPaid: number;
  amountDue: number;
  itemCount: number;
  source?: string;
  /** Historical first line label from order_items.product_name_snapshot. */
  firstProductName: string;
  branchId: string;
  createdAt: string;
  updatedAt: string;
}

const EMPTY_OPERATIONAL_ORDERS_SUMMARY: OperationalOrdersSummary = {
  review: 0,
  active: 0,
  due: 0,
};

const ORDER_DETAIL_SELECT = `
  id,
  order_number,
  customer_id,
  customer_name_snapshot,
  status,
  payment_method,
  payment_status,
  payment_reference_number,
  payment_confirmed_at,
  payment_confirmed_by,
  cash_shift_id,
  subtotal_in_minor_units,
  delivery_fee_in_minor_units,
  delivery_zone,
  discount_in_minor_units,
  promotion_code_snapshot,
  total_in_minor_units,
  amount_paid_in_minor_units,
  customer_notes,
  internal_notes,
  whatsapp_message,
  tracking_token,
  public_receipt_token,
  delivery_started_at,
  estimated_arrival_at,
  delivery_completed_at,
  delivery_driver_phone,
  source,
  branch_id,
  warehouse_id,
  created_at,
  updated_at,
  customers (
    id,
    full_name,
    phone,
    email
  ),
  customer_addresses (
    id,
    governorate,
    city,
    area,
    street,
    building,
    floor,
    apartment,
    notes,
    latitude,
    longitude,
    formatted_address,
    google_maps_url,
    location_source,
    location_confirmed
  ),
  order_items (
    id,
    commercial_line_kind,
    base_unit_name_snapshot,
    product_id,
    product_name_snapshot,
    sku_snapshot,
    quantity,
    unit_price_in_minor_units,
    line_total_in_minor_units,
    sale_package_quantity,
    units_per_sale_package,
    sale_package_name_snapshot,
    sale_package_price_in_minor_units,
    products!order_items_product_id_fkey (
      id,
      cost_price_in_minor_units,
      base_unit:units!products_unit_id_fkey (
        name_ar
      ),
      product_images (
        image_url
      )
    )
  ),
  order_status_history (
    id,
    old_status,
    new_status,
    changed_by,
    notes,
    created_at
  ),
  sales_returns (
    id,
    return_number,
    reason,
    stock_disposition,
    refund_method,
    refund_amount_in_minor_units,
    reference_number,
    created_at
  )
`;

const OPERATIONAL_ORDER_LIST_SELECT = `
  id,
  order_number,
  customer_name_snapshot,
  status,
  payment_method,
  payment_status,
  total_in_minor_units,
  amount_paid_in_minor_units,
  source,
  branch_id,
  created_at,
  updated_at,
  customers (
    full_name,
    phone
  ),
  customer_addresses (
    governorate,
    city,
    area
  ),
  order_items (count)
`;

const OPERATIONAL_ORDER_ITEM_PREVIEW_SELECT = `
  id,
  order_id,
  product_name_snapshot,
  created_at
`;

const MAX_OPERATIONAL_ORDER_ITEMS = 50;

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

const asNonNegativeInteger = (value: unknown, fallback = 0): number => {
  const parsed = Number(value);
  return Number.isInteger(parsed) && parsed >= 0 ? parsed : fallback;
};

const asPositiveInteger = (value: number, fallback: number): number =>
  Number.isInteger(value) && value > 0 ? value : fallback;

function parseOperationalOrdersPagePayload(value: unknown): {
  orderIds: string[];
  totalCount: number;
  summary: OperationalOrdersSummary;
} | null {
  if (!isRecord(value) || !Array.isArray(value.order_ids)) return null;

  const summary = isRecord(value.summary) ? value.summary : {};
  return {
    orderIds: value.order_ids.filter(
      (orderId): orderId is string => typeof orderId === 'string'
    ),
    totalCount: asNonNegativeInteger(value.total_count),
    summary: {
      review: asNonNegativeInteger(summary.review_count),
      active: asNonNegativeInteger(summary.active_count),
      due: asNonNegativeInteger(summary.due_in_minor_units) / 1000,
    },
  };
}

function toPaymentMethod(value: unknown): PaymentMethod {
  return paymentMethods.includes(value as PaymentMethod)
    ? (value as PaymentMethod)
    : 'cash_on_delivery';
}

function toPaymentStatus(value: unknown): PaymentStatus {
  return paymentStatuses.includes(value as PaymentStatus)
    ? (value as PaymentStatus)
    : 'unpaid';
}

async function fetchOperationalOrderListRows(
  orderIds: readonly string[]
): Promise<{
  success: boolean;
  orders: OperationalOrderListItem[];
  error?: string;
}> {
  if (!isSupabaseConfigured || !supabase) {
    return {
      success: false,
      orders: [],
      error: 'لم يتم إعداد عميل Supabase بنجاح.',
    };
  }

  if (orderIds.length === 0) {
    return { success: true, orders: [] };
  }

  try {
    const previewLimit = orderIds.length * MAX_OPERATIONAL_ORDER_ITEMS;
    const [ordersResult, previewsResult] = await Promise.all([
      supabase
        .from('orders')
        .select(OPERATIONAL_ORDER_LIST_SELECT)
        .in('id', [...orderIds]),
      supabase
        .from('order_items')
        .select(OPERATIONAL_ORDER_ITEM_PREVIEW_SELECT)
        .in('order_id', [...orderIds])
        .order('order_id', { ascending: true })
        .order('created_at', { ascending: true })
        .order('id', { ascending: true })
        .limit(previewLimit),
    ]);

    const { data, error } = ordersResult;

    if (error) {
      console.error('[fetchOperationalOrderListRows Error]:', error);
      return { success: false, orders: [], error: error.message };
    }

    if (!data) {
      return { success: true, orders: [] };
    }

    if (previewsResult.error) {
      console.error(
        '[fetchOperationalOrderListRows Preview Error]:',
        previewsResult.error
      );
    }

    const firstProductNamesByOrderId = mapFirstProductNamesByOrderId(
      previewsResult.error ? [] : previewsResult.data
    );

    return {
      success: true,
      orders: mapOperationalOrderListRows(data, firstProductNamesByOrderId),
    };
  } catch (error) {
    console.error('[fetchOperationalOrderListRows Exception]:', error);
    return {
      success: false,
      orders: [],
      error:
        error instanceof Error
          ? error.message
          : 'حدث خطأ غير متوقع أثناء جلب صفحة الطلبات.',
    };
  }
}

function mapFirstProductNamesByOrderId(value: unknown): Map<string, string> {
  const firstProductNames = new Map<string, string>();
  if (!Array.isArray(value)) return firstProductNames;

  value.forEach((row) => {
    if (!isRecord(row)) return;
    const orderId = typeof row.order_id === 'string' ? row.order_id : '';
    const productName =
      typeof row.product_name_snapshot === 'string'
        ? row.product_name_snapshot.trim()
        : '';
    if (!orderId || !productName || firstProductNames.has(orderId)) return;
    firstProductNames.set(orderId, productName);
  });

  return firstProductNames;
}

function firstRelation(value: unknown): Record<string, unknown> {
  if (Array.isArray(value)) {
    return isRecord(value[0]) ? value[0] : {};
  }
  return isRecord(value) ? value : {};
}

function mapOperationalOrderListRows(
  data: unknown[],
  firstProductNamesByOrderId: ReadonlyMap<string, string> = new Map()
): OperationalOrderListItem[] {
  return data.flatMap((value) => {
    if (!isRecord(value) || typeof value.id !== 'string') return [];

    const customer = firstRelation(value.customers);
    const address = firstRelation(value.customer_addresses);
    const itemCountRelation = firstRelation(value.order_items);
    const totalAmount = Number(value.total_in_minor_units || 0) / 1000;
    const amountPaid = Number(value.amount_paid_in_minor_units || 0) / 1000;

    return [{
      id: value.id,
      orderNumber:
        typeof value.order_number === 'string' ? value.order_number : value.id,
      customerName:
        typeof customer.full_name === 'string'
          ? customer.full_name
          : typeof value.customer_name_snapshot === 'string'
            ? value.customer_name_snapshot
            : 'زبون نقدي',
      customerPhone:
        typeof customer.phone === 'string' ? customer.phone : '',
      governorate:
        typeof address.governorate === 'string'
          ? address.governorate
          : 'غير محدد',
      region:
        typeof address.area === 'string'
          ? address.area
          : typeof address.city === 'string'
            ? address.city
            : 'غير محدد',
      status:
        typeof value.status === 'string'
          ? (value.status as OrderStatus)
          : 'new',
      paymentMethod: toPaymentMethod(value.payment_method),
      paymentStatus: toPaymentStatus(value.payment_status),
      totalAmount,
      amountPaid,
      amountDue: calculateOrderAmountDue(totalAmount, amountPaid),
      itemCount: asNonNegativeInteger(itemCountRelation.count),
      firstProductName: firstProductNamesByOrderId.get(value.id) || '',
      source: typeof value.source === 'string' ? value.source : undefined,
      branchId: typeof value.branch_id === 'string' ? value.branch_id : '',
      createdAt:
        typeof value.created_at === 'string'
          ? value.created_at
          : new Date(0).toISOString(),
      updatedAt:
        typeof value.updated_at === 'string'
          ? value.updated_at
          : typeof value.created_at === 'string'
            ? value.created_at
            : new Date(0).toISOString(),
    }];
  });
}

function mapOrderRows(data: unknown[]): Order[] {
  return data.map((ord: any) => {
    const cust = ord.customers || {};
    const addr = ord.customer_addresses || {};

    const items = (ord.order_items || []).map((item: any) => {
      const prod = item.products || {};
      const unitPrice = Number(item.unit_price_in_minor_units || 0) / 1000;
      const lineTotal = Number(item.line_total_in_minor_units || 0) / 1000;
      const costPrice = Number(prod.cost_price_in_minor_units || 0) / 1000;
      const packageQuantity = Number(item.sale_package_quantity || 0);
      const unitsPerSalePackage = Number(item.units_per_sale_package || 0);
      const isWholesaleSnapshot = packageQuantity > 0 && unitsPerSalePackage > 0;
      const displayQuantity = isWholesaleSnapshot
        ? packageQuantity
        : Number(item.quantity || 1);
      const displayUnitPrice = isWholesaleSnapshot
        ? Number(item.sale_package_price_in_minor_units || 0) / 1000
        : unitPrice;

      const unitName = isWholesaleSnapshot
        ? item.sale_package_name_snapshot || 'طرد'
        : prod.base_unit?.name_ar || prod.unit || 'قطعة';
      const imgUrl =
        Array.isArray(prod.product_images) && prod.product_images.length > 0
          ? prod.product_images[0].image_url
          : prod.image_url || '';

      return {
        id: item.id,
        productId: item.product_id || '',
        productName: item.product_name_snapshot || 'منتج',
        productImage: imgUrl,
        sku: item.sku_snapshot || '',
        unit: unitName,
        unitPrice: displayUnitPrice,
        costPrice,
        quantity: displayQuantity,
        baseQuantity: Number(item.quantity || 1),
        unitsPerSalePackage: unitsPerSalePackage || undefined,
        salePackage: isWholesaleSnapshot ? unitName : undefined,
        discount: 0,
        totalPrice: lineTotal,
        commercialLineKind: item.commercial_line_kind || undefined,
        baseUnitName: item.base_unit_name_snapshot || undefined,
      };
    });

    const statusHistory = (ord.order_status_history || [])
      .map((h: any) => ({
        status: (h.new_status || 'new') as OrderStatus,
        changedAt: h.created_at || new Date().toISOString(),
        changedBy: h.changed_by || 'النظام',
        reason: h.notes || undefined,
      }))
      .sort(
        (a: any, b: any) =>
          new Date(b.changedAt).getTime() - new Date(a.changedAt).getTime()
      );

    const parsedLat = addr.latitude == null ? undefined : Number(addr.latitude);
    const parsedLng = addr.longitude == null ? undefined : Number(addr.longitude);
    const coordinatesValid = validMapCoordinates(parsedLat, parsedLng);
    const lat = coordinatesValid ? parsedLat : undefined;
    const lng = coordinatesValid ? parsedLng : undefined;
    const gMapsUrl = safeGoogleMapsUrl(addr.google_maps_url, lat, lng);

    const addressStr =
      addr.formatted_address ||
      [addr.governorate, addr.city, addr.area, addr.street, addr.building]
        .filter(Boolean)
        .join(' - ') ||
      'عنوان غير محدد';
    const totalAmount = Number(ord.total_in_minor_units || 0) / 1000;
    const amountPaid = Number(ord.amount_paid_in_minor_units || 0) / 1000;
    const salesReturn = Array.isArray(ord.sales_returns)
      ? ord.sales_returns[0]
      : ord.sales_returns;

    return {
      id: ord.id,
      orderNumber: ord.order_number,
      customerId: cust.id || ord.customer_id || undefined,
      customerName: cust.full_name || ord.customer_name_snapshot || 'زبون نقدي',
      customerPhone: cust.phone || '',
      governorate: addr.governorate || 'غير محدد',
      region: addr.area || addr.city || 'غير محدد',
      address: addressStr,
      customerAddress: {
        governorate: addr.governorate,
        area: addr.area,
        street: addr.street,
        building: addr.building,
        apartment: addr.apartment,
        landmark: addr.city,
        deliveryNotes: addr.notes,
      },
      latitude: lat,
      longitude: lng,
      formattedAddress: addr.formatted_address,
      googleMapsUrl: gMapsUrl,
      mapUrl: !gMapsUrl && typeof addr.google_maps_url === 'string' ? addr.google_maps_url : undefined,
      locationSource: addr.location_source || 'manual',
      locationConfirmed: Boolean(addr.location_confirmed),
      trackingToken: ord.tracking_token || undefined,
      publicReceiptUrl: ord.public_receipt_token?storefrontReceiptUrl(ord.public_receipt_token):undefined,
      deliveryStartedAt: ord.delivery_started_at || undefined,
      estimatedArrivalAt: ord.estimated_arrival_at || undefined,
      deliveryCompletedAt: ord.delivery_completed_at || undefined,
      deliveryDriverPhone: ord.delivery_driver_phone || undefined,
      items,
      subtotal: Number(ord.subtotal_in_minor_units || 0) / 1000,
      deliveryFee: Number(ord.delivery_fee_in_minor_units || 0) / 1000,
      deliveryZone:
        ord.delivery_zone === 'inside_ramtha' || ord.delivery_zone === 'outside_ramtha'
          ? ord.delivery_zone
          : undefined,
      discount: Number(ord.discount_in_minor_units || 0) / 1000,
      promotionCode: ord.promotion_code_snapshot || undefined,
      totalAmount,
      amountPaid,
      amountDue: calculateOrderAmountDue(totalAmount, amountPaid),
      paymentMethod: toPaymentMethod(ord.payment_method),
      paymentStatus: toPaymentStatus(ord.payment_status),
      paymentReferenceNumber: ord.payment_reference_number || undefined,
      paymentConfirmedAt: ord.payment_confirmed_at || undefined,
      paymentConfirmedBy: ord.payment_confirmed_by || undefined,
      cashShiftId: ord.cash_shift_id || undefined,
      returnNumber: salesReturn?.return_number || undefined,
      returnReason: salesReturn?.reason || undefined,
      returnStockDisposition: salesReturn?.stock_disposition || undefined,
      refundMethod: salesReturn?.refund_method || undefined,
      refundAmount: salesReturn
        ? Number(salesReturn.refund_amount_in_minor_units || 0) / 1000
        : undefined,
      refundReferenceNumber: salesReturn?.reference_number || undefined,
      returnedAt: salesReturn?.created_at || undefined,
      source: ord.source || 'website',
      status: (ord.status as OrderStatus) || 'new',
      branchId: ord.branch_id || '',
      isNew: ord.status === 'new',
      notes: ord.customer_notes,
      internalNotes: ord.internal_notes,
      createdAt: ord.created_at,
      updatedAt: ord.updated_at,
      statusHistory,
    };
  });
}

export async function fetchOrderByIdFromSupabase(
  orderId: string
): Promise<{ success: boolean; order?: Order; error?: string }> {
  if (!isSupabaseConfigured || !supabase) {
    return { success: false, error: 'عميل Supabase غير غير معد.' };
  }

  try {
    const { data, error } = await supabase
      .from('orders')
      .select(ORDER_DETAIL_SELECT)
      .eq('id', orderId)
      .single();

    if (error) {
      if (error.code === 'PGRST116') {
        return { success: false, error: 'الطلب غير موجود في قاعدة البيانات.' };
      }

      console.error('[fetchOrderByIdFromSupabase Error]:', error);
      return { success: false, error: error.message };
    }

    const [order] = mapOrderRows([data]);
    if (!order) {
      return { success: false, error: 'الطلب غير موجود في قاعدة البيانات.' };
    }

    const parcelItems = order.items.filter((item) => item.commercialLineKind === 'configurable_parcel');
    if (parcelItems.length > 0) {
      const instancesResult = await supabase.from('order_parcel_instances')
        .select('id,order_item_id,instance_sequence,units_per_parcel_snapshot,parcel_unit_name_snapshot')
        .eq('order_id', orderId).order('instance_sequence');
      if (instancesResult.error) throw instancesResult.error;
      const instances = instancesResult.data || [];
      const componentsResult = instances.length > 0
        ? await supabase.from('order_parcel_components')
          .select('id,parcel_instance_id,product_id,base_quantity,product_name_snapshot,sku_snapshot,base_unit_name_snapshot')
          .in('parcel_instance_id', instances.map((instance) => instance.id))
        : { data: [], error: null };
      if (componentsResult.error) throw componentsResult.error;
      attachHistoricalParcelComposition(order, instances, componentsResult.data || []);
    }
    if(order.paymentMethod==='exchange_credit'){
      const funding=await supabase.rpc('get_order_exchange_details_v1',{p_order_id:orderId});
      if(funding.error)throw funding.error;
      order.exchangeFunding=orderExchangeFunding(orderId,funding.data);
    }
    return { success: true, order };
  } catch (err: any) {
    return { success: false, error: err?.message || 'تعذر جلب تفاصيل الطلب.' };
  }
}

export async function confirmOrderInSupabase(
  orderId: string,
  notes?: string
): Promise<{ success: boolean; message?: string; rawJson?: any; error?: string }> {
  if (!isSupabaseConfigured || !supabase) {
    return { success: false, error: 'عميل Supabase غير متاح.' };
  }

  try {
    const { data, error } = await supabase.rpc('accept_order_for_preparation', {
      p_order_id: orderId,
      p_notes: notes || null,
    });

    if (error) {
      console.error('[confirmOrderInSupabase Error]:', error);
      return { success: false, error: error.message, rawJson: error };
    }

    return {
      success: true,
      rawJson: data,
      message: data?.message || 'تم قبول الطلب وبدء التجهيز.',
    };
  } catch (err: any) {
    return { success: false, error: err?.message || 'حدث خطأ أثناء تأكيد الطلب.' };
  }
}

export async function completeWebsiteOrderWithPaymentInSupabase(
  orderId: string,
  paymentMethod: 'cash' | 'cliq',
  referenceNumber?: string,
  notes?: string
): Promise<{ success: boolean; message?: string; rawJson?: any; error?: string }> {
  if (!isSupabaseConfigured || !supabase) {
    return { success: false, error: 'عميل Supabase غير متاح.' };
  }

  try {
    if (await isCustomerV2Order(supabase, orderId)) {
      return { success: false, error: 'طلب Customer V2 يتطلب إكماله عبر التسوية المالية المعتمدة.' };
    }
    const { data, error } = await supabase.rpc(
      'complete_website_order_with_payment',
      {
        p_order_id: orderId,
        p_payment_method: paymentMethod,
        p_reference_number: referenceNumber?.trim() || null,
        p_notes: notes || null,
      }
    );

    if (error) {
      console.error(
        '[completeWebsiteOrderWithPaymentInSupabase Error]:',
        error
      );
      return { success: false, error: error.message, rawJson: error };
    }

    return {
      success: true,
      rawJson: data,
      message:
        data?.message ||
        'تم تأكيد القبض والتسليم وخصم الكميات من المخزون.',
    };
  } catch (err: any) {
    return {
      success: false,
      error: err?.message || 'حدث خطأ أثناء تأكيد قبض وتسليم الطلب.',
    };
  }
}

export async function cancelOrderInSupabase(
  orderId: string,
  notes?: string
): Promise<{ success: boolean; message?: string; rawJson?: any; error?: string }> {
  if (!isSupabaseConfigured || !supabase) {
    return { success: false, error: 'عميل Supabase غير متاح.' };
  }

  try {
    const customerV2 = await isCustomerV2Order(supabase, orderId);
    const { data, error } = customerV2
      ? await runCustomerV2AdminAction(supabase, orderId, 'cancel', { reason: notes || null })
      : await supabase.rpc('update_order_status', {
        p_order_id: orderId,
        p_new_status: 'cancelled',
        p_notes: notes || null,
      });

    if (error) {
      console.error('[cancelOrderInSupabase Error]:', error);
      return { success: false, error: error.message, rawJson: error };
    }

    return {
      success: true,
      rawJson: data,
      message: data?.message || 'تم إلغاء الطلب وتحرير الكمية المحجوزة.',
    };
  } catch (err: any) {
    return { success: false, error: err?.message || 'حدث خطأ أثناء إلغاء الطلب.' };
  }
}

export async function fetchOperationalOrdersPageFromSupabase(
  input: OperationalOrdersPageInput
): Promise<OperationalOrdersPage> {
  const page = asPositiveInteger(input.page, 1);
  const pageSize = Math.min(100, asPositiveInteger(input.pageSize, 25));
  const sort = input.sort === 'oldest' ? 'oldest' : 'newest';
  const searchQuery = input.searchQuery?.trim() || null;

  if (!isSupabaseConfigured || !supabase) {
    return {
      success: false,
      orders: [],
      page,
      pageSize,
      totalCount: 0,
      totalPages: 1,
      summary: EMPTY_OPERATIONAL_ORDERS_SUMMARY,
      error: 'لم يتم إعداد عميل Supabase بنجاح.',
    };
  }

  try {
    const { data, error } = await supabase.rpc('get_operational_orders_page', {
      p_page: page,
      p_page_size: pageSize,
      p_filter: input.filter,
      p_search: searchQuery,
      p_sort: sort,
    });

    if (error) {
      console.error('[fetchOperationalOrdersPageFromSupabase Error]:', error);
      return {
        success: false,
        orders: [],
        page,
        pageSize,
        totalCount: 0,
        totalPages: 1,
        summary: EMPTY_OPERATIONAL_ORDERS_SUMMARY,
        error: error.message,
      };
    }

    const pagePayload = parseOperationalOrdersPagePayload(data);
    if (!pagePayload) {
      return {
        success: false,
        orders: [],
        page,
        pageSize,
        totalCount: 0,
        totalPages: 1,
        summary: EMPTY_OPERATIONAL_ORDERS_SUMMARY,
        error: 'استجابة صفحة الطلبات غير صالحة.',
      };
    }

    if (pagePayload.orderIds.length === 0) {
      return {
        success: true,
        orders: [],
        page,
        pageSize,
        totalCount: pagePayload.totalCount,
        totalPages: Math.max(1, Math.ceil(pagePayload.totalCount / pageSize)),
        summary: pagePayload.summary,
      };
    }

    const listResult = await fetchOperationalOrderListRows(
      pagePayload.orderIds
    );
    if (!listResult.success) {
      return {
        success: false,
        orders: [],
        page,
        pageSize,
        totalCount: pagePayload.totalCount,
        totalPages: Math.max(1, Math.ceil(pagePayload.totalCount / pageSize)),
        summary: pagePayload.summary,
        error: listResult.error || 'تعذر تحميل صفحة الطلبات.',
      };
    }

    const ordersById = new Map(
      listResult.orders.map((order) => [order.id, order])
    );
    const orders = pagePayload.orderIds.flatMap((orderId) => {
      const order = ordersById.get(orderId);
      return order ? [order] : [];
    });

    return {
      success: true,
      orders,
      page,
      pageSize,
      totalCount: pagePayload.totalCount,
      totalPages: Math.max(1, Math.ceil(pagePayload.totalCount / pageSize)),
      summary: pagePayload.summary,
    };
  } catch (error) {
    const message =
      error instanceof Error ? error.message : 'تعذر تحميل صفحة الطلبات.';
    console.error('[fetchOperationalOrdersPageFromSupabase Exception]:', error);
    return {
      success: false,
      orders: [],
      page,
      pageSize,
      totalCount: 0,
      totalPages: 1,
      summary: EMPTY_OPERATIONAL_ORDERS_SUMMARY,
      error: message,
    };
  }
}

